/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.effective_max_attempts();
    let mut attempts = 0;
    let mut delay = config.base_delay_ms;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                let delay = delay.min(config.max_delay_ms);
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

